$hpfPath = Join-Path $tempDir "Contents\content.hpf"
if (Test-Path $hpfPath) {
    $hpf = [System.IO.File]::ReadAllText($hpfPath, [System.Text.Encoding]::UTF8)
    $hpf = $hpf -replace '<dc:title>[^<]*</dc:title>', '<dc:title>골목엔 나홀로 사장 보도자료</dc:title>'
    [System.IO.File]::WriteAllText($hpfPath, $hpf, [System.Text.Encoding]::UTF8)
}

# PrvText 업데이트
$prvPath = Join-Path $tempDir "Preview\PrvText.txt"
if (Test-Path $prvPath) {
    [System.IO.File]::WriteAllText($prvPath, "골목엔 나홀로 사장 방 안엔 쉬는 청년 무너진 고용 사다리 보도자료 2026.11.19.", [System.Text.Encoding]::UTF8)
}

# ── ZIP 파일 직접 작성 (mimetype = STORED, 방식=0x0000) ───────────────────────
if (Test-Path $outHwpx) { Remove-Item $outHwpx -Force }

# CRC32 계산 함수
function Get-CRC32 {
    param([byte[]]$data)
    $crc = 0xFFFFFFFF
    $table = New-Object uint32[] 256
    for ($i = 0; $i -lt 256; $i++) {
        $c = [uint32]$i
        for ($j = 0; $j -lt 8; $j++) {
            if ($c -band 1) { $c = 0xEDB88320 -bxor ($c -shr 1) }
            else { $c = $c -shr 1 }
        }
        $table[$i] = $c
    }
    foreach ($b in $data) {
        $crc = $table[($crc -bxor $b) -band 0xFF] -bxor ($crc -shr 8)
    }
    return $crc -bxor 0xFFFFFFFF
}

# 파일 목록 (순서 중요: mimetype 첫 번째)
$files = @(
    @{path=""; name="mimetype"; data=[System.Text.Encoding]::ASCII.GetBytes("application/haansofthwp"); compress=$false},
    @{path="version.xml"; name="version.xml"; data=$null; compress=$true},
    @{path="Contents\header.xml"; name="Contents/header.xml"; data=$null; compress=$true},
    @{path="BinData\image1.jpg"; name="BinData/image1.jpg"; data=$null; compress=$true},
    @{path="BinData\image2.jpg"; name="BinData/image2.jpg"; data=$null; compress=$true},
    @{path="Contents\section0.xml"; name="Contents/section0.xml"; data=$null; compress=$true},
    @{path="Preview\PrvText.txt"; name="Preview/PrvText.txt"; data=$null; compress=$true},
    @{path="Scripts\headerScripts.js"; name="Scripts/headerScripts.js"; data=$null; compress=$true},
    @{path="Scripts\sourceScripts.js"; name="Scripts/sourceScripts.js"; data=$null; compress=$true},
    @{path="settings.xml"; name="settings.xml"; data=$null; compress=$true},
    @{path="Preview\PrvImage.png"; name="Preview/PrvImage.png"; data=$null; compress=$true},
    @{path="META-INF\container.rdf"; name="META-INF/container.rdf"; data=$null; compress=$true},
    @{path="Contents\content.hpf"; name="Contents/content.hpf"; data=$null; compress=$true},
    @{path="META-INF\container.xml"; name="META-INF/container.xml"; data=$null; compress=$true},
    @{path="META-INF\manifest.xml"; name="META-INF/manifest.xml"; data=$null; compress=$true}
)

# 파일 데이터 로드
foreach ($f in $files) {
    if ($f.data -eq $null -and $f.path -ne "") {
        $fullPath = Join-Path $tempDir $f.path
        if (Test-Path $fullPath) {
            $f.data = [System.IO.File]::ReadAllBytes($fullPath)
        }
    }
}

# ZIP 구조 직접 작성
$outStream = New-Object System.IO.MemoryStream
$centralDirs = @()
$dosDate = 0x5673  # 2026-11-19
$dosTime = 0x8000  # 16:00

foreach ($f in $files) {
    if ($f.data -eq $null) { continue }
    
    $nameBytes = [System.Text.Encoding]::UTF8.GetBytes($f.name)
    $rawData = $f.data
    $crc = Get-CRC32 -data $rawData
    $offset = $outStream.Position
    
    if ($f.compress) {
        # DEFLATE 압축
        $compStream = New-Object System.IO.MemoryStream
        $deflate = New-Object System.IO.Compression.DeflateStream($compStream, [System.IO.Compression.CompressionLevel]::Optimal)
        $deflate.Write($rawData, 0, $rawData.Length)
        $deflate.Close()
        $compData = $compStream.ToArray()
        $method = [uint16]8  # DEFLATE
        $writeData = $compData
    } else {
        $method = [uint16]0  # STORED
        $writeData = $rawData
    }
    
    # Local file header
    $lfh = New-Object System.IO.MemoryStream
    $w = New-Object System.IO.BinaryWriter($lfh)
    $w.Write([uint32]0x04034B50)  # signature
    $w.Write([uint16]20)           # version needed
    $w.Write([uint16]0)            # flags
    $w.Write($method)              # compression method
    $w.Write($dosTime)             # mod time
    $w.Write($dosDate)             # mod date
    $w.Write([uint32]$crc)         # CRC-32
    $w.Write([uint32]$writeData.Length)   # compressed size
    $w.Write([uint32]$rawData.Length)     # uncompressed size
    $w.Write([uint16]$nameBytes.Length)   # filename length
    $w.Write([uint16]0)            # extra field length
    $w.Write($nameBytes)           # filename
    $w.Flush()
    $lfhBytes = $lfh.ToArray()
    $outStream.Write($lfhBytes, 0, $lfhBytes.Length)
    $outStream.Write($writeData, 0, $writeData.Length)
    
    # Central directory record 저장
    $centralDirs += @{
        name=$nameBytes; method=$method; crc=$crc
        compSize=$writeData.Length; uncompSize=$rawData.Length
        offset=$offset; dosTime=$dosTime; dosDate=$dosDate
    }
    
    Write-Host "  추가: $($f.name) (원본=$($rawData.Length), 저장=$($writeData.Length), 방식=$method)"
}

# Central directory
$cdOffset = $outStream.Position
foreach ($cd in $centralDirs) {
    $cdr = New-Object System.IO.MemoryStream
    $w2 = New-Object System.IO.BinaryWriter($cdr)
    $w2.Write([uint32]0x02014B50)  # central dir signature
    $w2.Write([uint16]20)           # version made by
    $w2.Write([uint16]20)           # version needed
    $w2.Write([uint16]0)            # flags
    $w2.Write([uint16]$cd.method)   # compression method
    $w2.Write([uint16]$cd.dosTime)  # mod time
    $w2.Write([uint16]$cd.dosDate)  # mod date
    $w2.Write([uint32]$cd.crc)      # CRC-32
    $w2.Write([uint32]$cd.compSize) # compressed size
    $w2.Write([uint32]$cd.uncompSize) # uncompressed size
    $w2.Write([uint16]$cd.name.Length) # filename length
    $w2.Write([uint16]0)            # extra field length
    $w2.Write([uint16]0)            # comment length
    $w2.Write([uint16]0)            # disk number start
    $w2.Write([uint16]0)            # internal attributes
    $w2.Write([uint32]0)            # external attributes
    $w2.Write([uint32]$cd.offset)   # local header offset
    $w2.Write($cd.name)             # filename
    $w2.Flush()
    $cdrBytes = $cdr.ToArray()
    $outStream.Write($cdrBytes, 0, $cdrBytes.Length)
}

# End of central directory
$cdSize = $outStream.Position - $cdOffset
$eocd = New-Object System.IO.MemoryStream
$w3 = New-Object System.IO.BinaryWriter($eocd)
$w3.Write([uint32]0x06054B50)   # EOCD signature
$w3.Write([uint16]0)             # disk number
$w3.Write([uint16]0)             # disk with central dir
$w3.Write([uint16]$centralDirs.Count)  # entries on disk
$w3.Write([uint16]$centralDirs.Count)  # total entries
$w3.Write([uint32]$cdSize)       # central dir size
$w3.Write([uint32]$cdOffset)     # central dir offset
$w3.Write([uint16]0)             # comment length
$w3.Flush()
$eocdBytes = $eocd.ToArray()
$outStream.Write($eocdBytes, 0, $eocdBytes.Length)

# 파일 저장
[System.IO.File]::WriteAllBytes($outHwpx, $outStream.ToArray())
$outStream.Close()

$finalSize = (Get-Item $outHwpx).Length
Write-Host ""
Write-Host "=== 완료 ==="
Write-Host "출력: $outHwpx"
Write-Host "크기: $finalSize bytes"

# 검증: mimetype 첫 엔트리 확인
Add-Type -Assembly System.IO.Compression.FileSystem
$verify = [System.IO.Compression.ZipFile]::OpenRead($outHwpx)
$first = $verify.Entries[0]
Write-Host "첫 항목: $($first.FullName), 압축크기=$($first.CompressedLength), 원본=$($first.Length)"
$ms = $verify.Entries[0].Open()
$buf = New-Object byte[] 30
$n = $ms.Read($buf, 0, 30)
$ms.Close()
$verify.Dispose()
Write-Host "mimetype 내용: $([System.Text.Encoding]::ASCII.GetString($buf[0..($n-1)]))"

# 임시 디렉토리 삭제
Remove-Item $tempDir -Recurse -Force
Write-Host "완료"
